  `primary_number` varchar(30) DEFAULT NULL,
  `secondary_number` varchar(30) DEFAULT NULL,
  `nationality` varchar(100) DEFAULT NULL,
  `school_college` varchar(100) DEFAULT NULL,
  `department` varchar(100) DEFAULT NULL,
  `intake` varchar(50) DEFAULT NULL,
  `academic_status` enum('Active','Suspended','Withdrawn','Graduated') DEFAULT NULL,
  `discipline_status` enum('Good Standing','Probation','Suspended','Expelled') DEFAULT NULL,
  `financial_information` text DEFAULT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `guardian_name` varchar(255) DEFAULT NULL,
